"""What an auto-generated file application search can filter and order by, and how its row becomes data."""

from __future__ import annotations

from typing import override

from ai.backend.common.data.entity.types import RuntimeEntityID
from ai.backend.manager.data.auto_generated_file.types import AutoGeneratedFileApplicationData
from ai.backend.manager.models.auto_generated_file_application.row import (
    AutoGeneratedFileApplicationRow,
)
from ai.backend.manager.models.specs.conditions.string import StringConditions
from ai.backend.manager.models.specs.conditions.uuid import UUIDConditions
from ai.backend.manager.models.specs.orders.column import ColumnOrder
from ai.backend.manager.models.specs.search.converter import RowDataConverter
from ai.backend.manager.models.specs.search.field import SearchableField


class _AutoGeneratedFileApplicationOwnFields(
    RowDataConverter[AutoGeneratedFileApplicationRow, AutoGeneratedFileApplicationData]
):
    entity_type = SearchableField(
        AutoGeneratedFileApplicationRow.entity_type,
        StringConditions(AutoGeneratedFileApplicationRow.entity_type),
        ColumnOrder(AutoGeneratedFileApplicationRow.entity_type),
    )
    entity_id = SearchableField(
        AutoGeneratedFileApplicationRow.entity_id,
        UUIDConditions(AutoGeneratedFileApplicationRow.entity_id),
        ColumnOrder(AutoGeneratedFileApplicationRow.entity_id),
    )
    path = SearchableField(
        AutoGeneratedFileApplicationRow.path,
        StringConditions(AutoGeneratedFileApplicationRow.path),
        ColumnOrder(AutoGeneratedFileApplicationRow.path),
    )
    perm = SearchableField(AutoGeneratedFileApplicationRow.perm, None, None)
    file_id = SearchableField(
        AutoGeneratedFileApplicationRow.file_id,
        UUIDConditions(AutoGeneratedFileApplicationRow.file_id),
        ColumnOrder(AutoGeneratedFileApplicationRow.file_id),
    )

    @override
    def to_data(self, row: AutoGeneratedFileApplicationRow) -> AutoGeneratedFileApplicationData:
        return AutoGeneratedFileApplicationData(
            entity=RuntimeEntityID(self.entity_type.read(row), self.entity_id.read(row)),
            path=self.path.read(row),
            perm=self.perm.read(row),
            file_id=self.file_id.read(row),
        )


class AutoGeneratedFileApplicationSearchableFields:
    own = _AutoGeneratedFileApplicationOwnFields()
